import{_ as t,o as a,c,a2 as r}from"./chunks/framework.BS0bAV7E.js";const _=JSON.parse('{"title":"网络协议栈","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/network-stack.md","filePath":"zh/arch/network-stack.md"}'),o={name:"zh/arch/network-stack.md"};function n(s,e,d,i,h,l){return a(),c("div",null,[...e[0]||(e[0]=[r('<h1 id="网络协议栈" tabindex="-1">网络协议栈 <a class="header-anchor" href="#网络协议栈" aria-label="Permalink to &quot;网络协议栈&quot;">​</a></h1><p>自底向上，每层对应一个文件，位于 <code>net/</code> 目录下：</p><h2 id="网卡驱动-drivers-nic" tabindex="-1">网卡驱动 (<code>drivers/nic/</code>) <a class="header-anchor" href="#网卡驱动-drivers-nic" aria-label="Permalink to &quot;网卡驱动 (`drivers/nic/`)&quot;">​</a></h2><p>e1000、e1000e、igb、ixgbe（Intel 系列）；rtl8139 和 rtl8169 系列（8168/8125/810x）；BCM57xx。每个驱动通过 L1 driver_nic 接口（<code>driver_nic_register</code> / send / recv / link_status / get_mac）进行注册。DMA 描述符、支持中断驱动的 RX 以及每卡特殊处理均在驱动文件中实现 - 各系列的点亮说明 位于 <a href="./../drivers/">../drivers/</a>。</p><h2 id="以太网-arp" tabindex="-1">以太网 + ARP <a class="header-anchor" href="#以太网-arp" aria-label="Permalink to &quot;以太网 + ARP&quot;">​</a></h2><p>按以太网类型进行帧 RX 分发；带过期机制的 ARP 缓存； <code>arp</code> 命令。</p><h2 id="ipv4-icmp-udp" tabindex="-1">IPv4 / ICMP / UDP <a class="header-anchor" href="#ipv4-icmp-udp" aria-label="Permalink to &quot;IPv4 / ICMP / UDP&quot;">​</a></h2><p>分片处理、ICMP 回显（<code>ping</code> 命令）、UDP 套接字 - DNS 通过 UDP 运行，解析器通过网络配置设置。</p><h2 id="tcp-net-net-core-c-net-tcp-cc-c" tabindex="-1">TCP (<code>net/net_core.c</code> + <code>net_tcp_cc.c</code>) <a class="header-anchor" href="#tcp-net-net-core-c-net-tcp-cc-c" aria-label="Permalink to &quot;TCP (`net/net_core.c` + `net_tcp_cc.c`)&quot;">​</a></h2><p>包含拥塞控制的完整状态机。RX 校验和链曾是一个著名缺陷 （BUG-0072：链式 internet_checksum() 调用被重复补全 - 每个入站段均被拒绝；通过 checksum_raw_add + 在伪首部与 段之间进行一次折叠修复）。<code>tcpstats</code>、<code>tcpcc_test</code>、 <code>tcptest</code> 是观察者/测试程序。</p><h2 id="用户程序的套接字" tabindex="-1">用户程序的套接字 <a class="header-anchor" href="#用户程序的套接字" aria-label="Permalink to &quot;用户程序的套接字&quot;">​</a></h2><p>套接字系统调用族（53-syscall 接口）支持 <code>run select_test</code> 风格的复用以及网络用户程序。</p><h2 id="tls-1-2-1-3-net-net-tls-c" tabindex="-1">TLS 1.2 / 1.3 (<code>net/net_tls.c</code>) <a class="header-anchor" href="#tls-1-2-1-3-net-net-tls-c" aria-label="Permalink to &quot;TLS 1.2 / 1.3 (`net/net_tls.c`)&quot;">​</a></h2><p>RSA 和 ECDHE 密钥交换，X.509 链验证（采用 RFC 6125 主机名策略，IP 字面 URL 无参考身份 - 握手中断开连接的缺陷 正好在此处，通过 net_tls_host_is_ip_literal 修复）， 以及 WP-09 信任模型：结构边界始终致命；未锚定链会警告并 继续；主机名不匹配仅对用户提供的主名致命。</p><h2 id="ssh-客户端-服务器-net-ssh-c-net-sshd-c" tabindex="-1">SSH 客户端 + 服务器 (<code>net_ssh.c</code>, <code>net_sshd.c</code>) <a class="header-anchor" href="#ssh-客户端-服务器-net-ssh-c-net-sshd-c" aria-label="Permalink to &quot;SSH 客户端 + 服务器 (`net_ssh.c`, `net_sshd.c`)&quot;">​</a></h2><p>密钥交换、/etc 上的主机密钥、authorized_keys、完整会话 往返 - E2E 套件使用主机上的 paramiko 登录。</p><h2 id="熵" tabindex="-1">熵 <a class="header-anchor" href="#熵" aria-label="Permalink to &quot;熵&quot;">​</a></h2><p>HMAC_DRBG（SP 800-90A）从 RDRAND + RDTSC 播种，每次生成 时重新混合 - 参见 <a href="./../internals/drbg-crypto.html">internals/drbg-crypto.md</a>。</p>',18)])])}const u=t(o,[["render",n]]);export{_ as __pageData,u as default};
